tracks.example:
for (const track of kcds.players.Progression.tracks()) {
  console.info(`${track.name} (${track.kind}), cap ${track.cap}`);
}

tracks.exampleCs:
foreach (var track in Progression.Tracks())
{
    Log.Info($"{track["name"]} ({track["kind"]}), cap {track["cap"]}");
}

perkNamed.example:
const perk = kcds.players.Progression.perkNamed('Against all odds');
if (perk) {
  console.info(`${perk.name}: ${perk.track} level ${perk.level}`);
}

perkNamed.exampleCs:
var perk = Progression.PerkNamed("Against all odds");
if (perk)
{
    Log.Info($"{perk["name"]}: {perk["track"]} level {perk["level"]}");
}

setPerkText.example:
kcds.players.Progression.setPerkText('Against all odds', {
  name: "Racek's legacy",
  description: 'You fight on when others would fall.',
});
